import{_ as e}from"./chunks/buildings.CQ8vpPwC.js";import{_ as a,o as d,c as r,a0 as l}from"./chunks/framework.DYAX5gPL.js";const g=JSON.parse('{"title":"Vector Tiles vs. 3DTiles","description":"","frontmatter":{"title":"Vector Tiles vs. 3DTiles"},"headers":[],"relativePath":"en/api/vt-compare.md","filePath":"en/api/vt-compare.md"}'),i={name:"en/api/vt-compare.md"};function o(s,t,n,c,p,h){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="vector-tiles-vs-3dtiles" tabindex="-1">Vector Tiles vs. 3DTiles <a class="header-anchor" href="#vector-tiles-vs-3dtiles" aria-label="Permalink to &quot;Vector Tiles vs. 3DTiles&quot;">​</a></h1><p><img src="'+e+'" alt="City white model"></p><p>In the industry, 3D buildings converted from 2D vector data like those in the image above are commonly called white-model buildings.</p><p>Both vector tile layers and 3DTiles can render white-model buildings for large city scenes. Their main comparison:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th>Vector Tiles</th><th>3DTiles</th></tr></thead><tbody><tr><td style="text-align:left;">Data storage</td><td>Database or files</td><td>Static model files</td></tr><tr><td style="text-align:left;">Real-time data updates</td><td>✔</td><td>❌</td></tr><tr><td style="text-align:left;">Real-time style updates</td><td>✔</td><td>❌</td></tr><tr><td style="text-align:left;">Batch model rendering (I3DM)</td><td>✔</td><td>✔</td></tr><tr><td style="text-align:left;">Point cloud data</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">Oblique photography</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">3D generation strategy</td><td>Real-time generation on the frontend</td><td>Software conversion</td></tr><tr><td style="text-align:left;">Performance</td><td>High</td><td>Poor</td></tr><tr><td style="text-align:left;">Open-source ecosystem support</td><td>Rich</td><td>Limited</td></tr></tbody></table><p>Therefore, for rendering 3D white-model buildings, we believe vector tiles are the better technical solution.</p><p>However, for point cloud and oblique photography data, 3DTiles remains the best technical solution and cannot be replaced by vector tiles.</p><blockquote><p>This document has been cross-checked against the @maptalks/gl-layers 2026 source code (api-notes-vt-gl.md)</p></blockquote>',8)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
